// SMS send gate. Decides only; never sends. Keeps no state between calls.
// Marketing texts: 47 CFR 64.1200 (prior express written consent, revocation,
// 08:00 to before 21:00 at the recipient) and CTIA opt-in/opt-out practice.

const CALL_START = "08:00";
const CALL_END = "21:00";

const hold = (rule) => ({ allowed: false, rule });
const ok = () => ({ allowed: true, rule: "" });

export async function checkSend({ user, message, now } = {}) {
  try {
    const ms = now instanceof Date ? now.getTime() : NaN;
    if (!Number.isFinite(ms)) return hold("invalid-time");
    if (!user || typeof user !== "object") return hold("invalid-input");
    if (!message || typeof message !== "object") return hold("invalid-input");

    // Transactional: asked for by the customer or about an order they placed.
    // Not subject to marketing consent, calling hours or a STOP for marketing.
    if (message.kind === "transactional") return ok();

    // Anything else is marketing.
    const sms = user.sms && typeof user.sms === "object" ? user.sms : null;
    if (!sms) return hold("no-consent");

    // Opt-out beats everything. Any recorded value counts, even an unparseable one.
    const out = sms.optedOutAt;
    if (out !== null && out !== undefined && out !== "" && out !== false) return hold("opted-out");

    if (sms.optedIn !== true) return hold("no-consent");

    const zone = user.timeZone;
    if (typeof zone !== "string" || !zone.trim() || !gkZoneOk(zone)) return hold("invalid-time-zone");

    if (!gkInWindow(ms, zone, CALL_START, CALL_END)) return hold("outside-calling-hours");
    return ok();
  } catch {
    return hold("internal-error");
  }
}
EOF
